import{_ as a,a0 as o,w as n,s as p,I as s,x as i,a1 as l,A as d,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何使用命令行检查 Linux 上的磁盘空间 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用命令行检查 Linux 上的磁盘空间 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用命令行检查 Linux 上的磁盘空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用命令行检查 Linux 上的磁盘空间 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180622 How to Check Disk Space on Linux from the Command line","title":"如何使用命令行检查 Linux 上的磁盘空间","tag":"201808","desc":""},"relativePath":"201808/20180622 How to Check Disk Space on Linux from the Command line.md","filePath":"[post].md"}'),r={name:"201808/20180622 How to Check Disk Space on Linux from the Command line.md"};function c(k,e,m,h,g,f){const t=o("Link");return n(),p("div",null,[e[21]||(e[21]=s("h1",{id:"如何使用命令行检查-linux-上的磁盘空间",tabindex:"-1"},[i("如何使用命令行检查 Linux 上的磁盘空间 "),s("a",{class:"header-anchor",href:"#如何使用命令行检查-linux-上的磁盘空间","aria-label":"Permalink to “如何使用命令行检查 Linux 上的磁盘空间”"},"​")],-1)),e[22]||(e[22]=s("blockquote",null,[s("p",null,"Linux 提供了所有必要的工具来帮助你确切地发现你的驱动器上剩余多少空间。Jack 在这里展示了如何做。")],-1)),e[23]||(e[23]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace-main.jpg?itok=t9Oxxc9X",alt:""})],-1)),e[24]||(e[24]=s("p",null,"快速提问：你的驱动器剩余多少剩余空间？一点点还是很多？接下来的提问是：你知道如何找出这些剩余空间吗？如果你碰巧使用的是 GUI 桌面（ 例如 GNOME、KDE、Mate、Pantheon 等 ），则任务可能非常简单。但是，当你要在一个没有 GUI 桌面的服务器上查询剩余空间，你该如何去做呢？你是否要为这个任务安装相应的软件工具？答案是绝对不是。在 Linux 中，具备查找驱动器上的剩余磁盘空间的所有工具。事实上，有两个非常容易使用的工具。",-1)),s("p",null,[e[1]||(e[1]=i("在本文中，我将演示这些工具。我将使用 ",-1)),l(t,{href:"https://elementary.io/"},{default:d(()=>[...e[0]||(e[0]=[i("Elementary OS",-1)])]),_:1}),e[2]||(e[2]=i("（LCTT译注：Elementary OS 是基于 Ubuntu 精心打磨美化的桌面 Linux 发行版 ），它还包括一个 GUI 方式，但我们将限制自己仅使用命令行。好消息是这些命令行工具随时可用于每个 Linux 发行版。在我的测试系统中，连接了许多的驱动器（内部的和外部的）。使用的命令与连接驱动器的位置无关，仅仅与驱动器是否已经挂载好并且对操作系统可见有关。",-1))]),e[25]||(e[25]=u('<p>言归正传，让我们来试试这些工具。</p><h3 id="df" tabindex="-1">df <a class="header-anchor" href="#df" aria-label="Permalink to “df”">​</a></h3><p><code>df</code> 命令是我第一个用于在 Linux 上查询驱动器空间的工具，时间可以追溯到 20 世纪 90 年代。它的使用和报告结果非常简单。直到今天，<code>df</code> 还是我执行此任务的首选命令。此命令有几个选项开关，对于基本的报告，你实际上只需要一个选项。该命令是 <code>df -H</code> 。<code>-H</code> 选项开关用于将 <code>df</code> 的报告结果以人类可读的格式进行显示。<code>df -H</code> 的输出包括：已经使用了的空间量、可用空间、空间使用的百分比，以及每个磁盘连接到系统的挂载点（图 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_1.jpg?itok=aJa8AZAM" alt="df output"></p><p><em>图 1：Elementary OS 系统上 <code>df -H</code> 命令的输出结果</em></p><p>如果你的驱动器列表非常长并且你只想查看单个驱动器上使用的空间，该怎么办？对于 <code>df</code> 这没问题。我们来看一下位于 <code>/dev/sda1</code> 的主驱动器已经使用了多少空间。为此，执行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>df -H /dev/sda1</span></span></code></pre></div><p>输出将限于该驱动器（图 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_2.jpg?itok=_PAq3kxC" alt="disk usage"></p><p><em>图 2：一个单独驱动器空间情况</em></p><p>你还可以限制 <code>df</code> 命令结果报告中显示指定的字段。可用的字段包括：</p><ul><li><code>source</code> — 文件系统的来源（LCTT译注：通常为一个设备，如 <code>/dev/sda1</code> ）</li><li><code>size</code> — 块总数</li><li><code>used</code> — 驱动器已使用的空间</li><li><code>avail</code> — 可以使用的剩余空间</li><li><code>pcent</code> — 驱动器已经使用的空间占驱动器总空间的百分比</li><li><code>target</code> —驱动器的挂载点</li></ul><p>让我们显示所有驱动器的输出，仅显示 <code>size</code> ，<code>used</code> ，<code>avail</code> 字段。对此的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>df -H --output=size,used,avail</span></span></code></pre></div><p>该命令的输出非常简单（ 图 3 ）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_3.jpg?itok=51m8I-Vu" alt="output"></p><p><em>图 3：显示我们驱动器的指定输出</em></p><p>这里唯一需要注意的是我们不知道该输出的来源，因此，我们要把 <code>source</code> 加入命令中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>df -H --output=source,size,used,avail</span></span></code></pre></div><p>现在输出的信息更加全面有意义（图 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_4.jpg?itok=SuwgueN3" alt="source"></p><p><em>图 4：我们现在知道了磁盘使用情况的来源</em></p><h3 id="du" tabindex="-1">du <a class="header-anchor" href="#du" aria-label="Permalink to “du”">​</a></h3><p>我们的下一个命令是 <code>du</code> 。 正如您所料，这代表<ruby>磁盘使用情况<rt>disk usage</rt></ruby>。 <code>du</code> 命令与 <code>df</code> 命令完全不同，因为它报告目录而不是驱动器的空间使用情况。 因此，您需要知道要检查的目录的名称。 假设我的计算机上有一个包含虚拟机文件的目录。 那个目录是 <code>/media/jack/HALEY/VIRTUALBOX</code> 。 如果我想知道该特定目录使用了多少空间，我将运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -h /media/jack/HALEY/VIRTUALBOX</span></span></code></pre></div><p>上面命令的输出将显示目录中每个文件占用的空间（图 5）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_5.jpg?itok=XfS4s7Zq" alt="du command"></p><p><em>图 5 在特定目录上运行 <code>du</code> 命令的输出</em></p><p>到目前为止，这个命令并没有那么有用。如果我们想知道特定目录的总使用量怎么办？幸运的是，<code>du</code> 可以处理这项任务。对于同一目录，命令将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -sh /media/jack/HALEY/VIRTUALBOX/</span></span></code></pre></div><p>现在我们知道了上述目录使用存储空间的总和（图 6）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_6.jpg?itok=r71qICyG" alt="space used"></p><p><em>图 6：我的虚拟机文件使用存储空间的总和是 559GB</em></p><p>您还可以使用此命令查看父项的所有子目录使用了多少空间，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -h /media/jack/HALEY</span></span></code></pre></div><p>此命令的输出见（图 7），是一个用于查看各子目录占用的驱动器空间的好方法。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_7.jpg?itok=PtDe4q5y" alt="directories"></p><p><em>图 7：子目录的存储空间使用情况</em></p><p><code>du</code> 命令也是一个很好的工具，用于查看使用系统磁盘空间最多的目录列表。执行此任务的方法是将 <code>du</code> 命令的输出通过管道传递给另外两个命令：<code>sort</code> 和 <code>head</code> 。下面的命令用于找出驱动器上占用存储空间最大的前 10 个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -a /media/jack | sort -n -r |head -n 10</span></span></code></pre></div><p>输出将以从大到小的顺序列出这些目录（图 8）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_8.jpg?itok=v9E1SFcC" alt="top users"></p><p><em>图 8：使用驱动器空间最多的 10 个目录</em></p><h3 id="没有你想像的那么难" tabindex="-1">没有你想像的那么难 <a class="header-anchor" href="#没有你想像的那么难" aria-label="Permalink to “没有你想像的那么难”">​</a></h3><p>查看 Linux 系统上挂载的驱动器的空间使用情况非常简单。只要你将你的驱动器挂载在 Linux 系统上，使用 <code>df</code> 命令或 <code>du</code> 命令在报告必要信息方面都会非常出色。使用 <code>df</code> 命令，您可以快速查看磁盘上总的空间使用量，使用 <code>du</code> 命令，可以查看特定目录的空间使用情况。对于每一个 Linux 系统的管理员来说，这两个命令的结合使用是必须掌握的。</p>',45)),s("p",null,[e[4]||(e[4]=i("而且，如果你没有注意到，我最近介绍了",-1)),l(t,{href:"https://www.linux.com/learn/5-commands-checking-memory-usage-linux"},{default:d(()=>[...e[3]||(e[3]=[i("查看 Linux 上内存使用情况的方法",-1)])]),_:1}),e[5]||(e[5]=i("。总之，这些技巧将大力帮助你成功管理 Linux 服务器。",-1))]),e[26]||(e[26]=s("p",null,"通过 Linux Foundation 和 edX 免费提供的 “Linux 简介” 课程，了解更多有关 Linux 的信息。",-1)),e[27]||(e[27]=s("hr",null,null,-1)),s("p",null,[e[7]||(e[7]=i("via: ",-1)),l(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/6how-check-disk-space-linux-command-line"},{default:d(()=>[...e[6]||(e[6]=[i("https://www.linux.com/learn/intro-to-linux/2018/6how-check-disk-space-linux-command-line",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=i("作者：",-1)),l(t,{href:"https://www.linux.com/users/jlwallen"},{default:d(()=>[...e[8]||(e[8]=[i("Jack Wallen",-1)])]),_:1}),e[13]||(e[13]=i(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[9]||(e[9]=[i("lujun9972",-1)])]),_:1}),e[14]||(e[14]=i(" 译者：",-1)),l(t,{href:"https://github.com/SunWave"},{default:d(()=>[...e[10]||(e[10]=[i("SunWave",-1)])]),_:1}),e[15]||(e[15]=i(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[11]||(e[11]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=i("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[16]||(e[16]=[i("LCTT",-1)])]),_:1}),e[19]||(e[19]=i(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:d(()=>[...e[17]||(e[17]=[i("Linux中国",-1)])]),_:1}),e[20]||(e[20]=i(" 荣誉推出",-1))])])}const C=a(r,[["render",c]]);export{w as __pageData,C as default};
